var e={"29268u":`RoboKit — construisez et simulez une voiture robot`,qvztjl:`RoboKit — début du tutoriel`,s42iv2:`academe.com.br (s’ouvre dans un nouvel onglet)`,"16us7mj":`Langue`,ktdb8o:`Réglages`,"198kuu7":`Établi 3D`,ia581p:`Animation`,j4z771:`Pause`,wlqobg:`Pause (Espace)`,h23ysv:`Vitesse de lecture`,r953rm:`Zoom`,"19blqjd":`Zoom avant`,"110wpq2":`Zoom arrière`,q5w460:`Vue`,bldqt5:`Vue éclatée (E)`,"44cnpg":`Vue poursuite : suivre la voiture par l’arrière (C)`,"13epjbk":`Plan vu de dessus de l’arène d’essai`,j4zjee:`L’obstacle sélectionné`,yq1vr3:`Du centre de l’obstacle, depuis le centre de l’arène, où la voiture part tournée vers le haut du plan`,"19kd62s":`Personnaliser l’arène`,l1a70i:`Personnaliser l’arène : déplacer, tourner et redimensionner les obstacles`,"15n0apn":`Annuler la dernière modification (Ctrl+Z). Ctrl+Shift+Z la rétablit`,j4uzpn:`L’arène d’origine, avec la voiture ramenée à son départ`,"84sbk0":`Laisser l’arène telle qu’elle était (Échap)`,"1oy9vz":`Utiliser cette arène : la vue 3D est reconstruite et la simulation reprend`,ium5z9:`Comment le programme de la voiture décide`,vq0gg8:`Fermer l’organigramme`,s2tc63:`Fermer (Échap)`,"13bjj4d":`Passer la voiture en Auto et la regarder décider`,gfubiu:`Comment le programme décide : ouvrir l’organigramme`,"1gh0at8":`Étapes du tutoriel`,"61nq88":`Étapes précédentes`,ga5x9q:`Étapes suivantes`,"1v1ybkn":`Conduire`,"9anomo":`Avancer (W / ↑)`,bbake2:`Tourner à gauche (A / ←)`,bfl95g:`Arrêt (Espace)`,iseiwq:`Tourner à droite (D / →)`,"4o292l":`Reculer (S / ↓)`,"10qzszt":`Vitesse des moteurs`,"2yhdcy":`Mode de conduite`,"8m10x9":`Manuel (1)`,"1ogxhr7":`Évitement d’obstacles (2)`,"1i3ygcv":`Couper les moteurs (3)`,"1dlx0na":`Buzzer (B)`,isqcd9:`Angle du servo`,"29ulgm":`Sortie série`,"1l0xxoj":`Fermer`,"2r1h4p":`Connexion`,cwepyb:`Chargement…`,"10iu545":`RoboKit a besoin de JavaScript pour fonctionner.`,"120y7gz":`Conçu par`,"1hpelzf":`Carte`,"1j2fqe6":`ÉTABLI`,"17d8vhd":`Étape 1 · Rassemblez les pièces`,gqo5v1:`Simulateur`,"1py6ulk":`Cliquez pour inspecter`,"1ms3o1u":`Distance`,"2w2xwg":`Vitesse`,n44ilu:`Mode`,"1d2vfr6":`Servo`,"152va0w":`Simulation en pause`,"11i7yk1":`Cliquez sur un obstacle pour le sélectionner.`,"1a4x3zw":`Taille`,"1kpdcfp":`Longueur`,gfxz9b:`Largeur`,s3robe:`Diamètre`,"7puwki":`Hauteur`,kbxnhn:`Rotation`,"7nkn2r":`Position, depuis le départ`,v1hcj2:`Devant`,"1vf2pel":`À droite`,"1xakelj":`Maj`,"1esrfu8":`pas de 5 cm, 15°`,yvgdmk:`Alt`,"1w55ans":`taille depuis le centre`,"1xzs12p":`déplacer ·`,"14bbmnu":`tourner`,g7xa5b:`Arène · 3 × 3 m`,vmlwpb:`Annuler`,"2zps2o":`Réinitialiser`,ew9em3:`Annuler`,lewgh4:`Enregistrer`,"1vz8dhj":`Comment le programme décide`,m76rx7:`Choisissez une case pour voir son code`,"1hnif0x":`Déroulement du programme`,"11rknnz":`En direct`,"540b06":`Auto`,"1fr6xqr":`Rassemblez les pièces`,"1wu7r43":`Manuel`,ky4lc5:`Arrêt`,"152av8f":`Actionneurs`,"1df7dln":`Buzzer`,pksfl2:`conduire ·`,"1hrh82t":`Espace`,"9zyeew":`arrêt ·`,jw8yab:`mode ·`,j4ckle:`buzzer ·`,kzo6rh:`poursuite`,mcpijf:`Moniteur série`,"1aeugy":`Effacer`,"1jgmzoq":`← Retour`,c9ljxw:`étapes`,"1padbm0":`Suivant`,g6g542:`Retour à l’étape`,"1k7z1pa":`Échap`,dpexcn:`Caractéristiques`,"8f4gnm":`Aller à l’étape`,qy3p54:`RÉGLAGES`,"12znfuf":`L’étape de conduite se connecte à`,"17rhf7d":`Vraie voiture (Wi-Fi de l’ESP32)`,dsq8ip:`Adresse de la voiture`,"1ihj7t4":`Affichage et son`,oh792y:`Jouer le buzzer sur les haut-parleurs`,"1bxmuya":`Afficher le faisceau ultrasonique`,"1gxdv01":`La caméra suit la voiture`,"9mmtn3":`Réinitialiser la simulation`,"1k6e5zv":`Appliquer`,"1iptqu5":`URL non valide « {url} »`,"12bfr2h":`L’URL doit commencer par ws:// ou wss://`,"1s22nop":`Connexion à {url}`,"1q17yrm":`Nouvel essai dans {s} s`,hsi0bv:`Aucune donnée de la voiture`,ye8ewg:`Connecté`,"1puhp9v":`Connexion…`,y1y3f2:`Aucune donnée`,ci4tze:`Déconnecté`,"1fmx9lv":`Erreur de connexion`,"19wtqq3":`Connecté · {board}`,"1b4ym3j":`Simulateur intégré`,bgnl0z:`Préparation des graphismes`,"39rjx0":`Prêt`,"1ruee97":`L’établi 3D n’a pas pu démarrer. Il lui faut WebGL : essayez un autre navigateur ou activez l’accélération matérielle.`,xa5swu:`ARÈNE D’ESSAI`,"18xfupg":`Conduisez avec les commandes à droite`,khccvm:`Conduisez avec W A S D ou les commandes à droite`,vhwww6:`Étape {n} · {title}`,"1i98668":`Construction de la voiture`,y9b5jm:`Disposition des pièces`,qzfxj5:`Montrer la ligne {n} sur l’établi`,pj86x7:`Montrer ceci sur l’établi`,"13bzcw5":`Copié`,"8gdme8":`Sélectionnez et copiez`,s6g5lw:`Copier`,"1bstp0v":`Liste du matériel`,"1g4j0cl":`Il vous faut`,"15cdqf0":`Outils`,"1wrxvmg":`À faire`,"1x0ptmh":`Brochage · {board}`,"1go9otx":`Sketches`,zvnhd5:`Sketch`,t8quxl:`Télécharger`,na9qmv:`En cas de problème`,"5mau71":`Remarque`,"1xh5jos":`{kicker} · Étape {n} sur {total}`,slbawy:`Suivant : {step} →`,"7rhhil":`Recommencer ↺`,"1mtyvb1":`Étape {n} : {step} · {done} / {total} cochés`,"4x1xaj":`Étape {n} : {step}`,d2gue0:`Carton`,"1xebpbq":`Bloc de bois`,hi63vm:`Boîte de conserve`,"14yz9o9":`Pot de fleurs`,"1g6nbya":`Il doit rester à l’intérieur des murs.`,v23nvk:`Le point de départ de la voiture doit rester libre.`,"1d1sqge":`La voiture se trouve là.`,sjcnug:`Deux obstacles ne peuvent pas occuper la même place.`,"1rjq9tt":`Faites glisser un obstacle pour le déplacer. Ses poignées carrées changent sa taille, la ronde le fait tourner.`,qaws2z:`L’arène vue de dessus. Cliquez sur un obstacle pour le sélectionner, faites-le glisser pour le déplacer. Au clavier : Page suivante et Page précédente sélectionnent un obstacle, les flèches le déplacent, R le fait tourner.`,km6rtw:`Obstacle`,v6zgjh:`L’arène d’origine. L’enregistrer ramène la voiture à son départ.`,"1bneya5":`Chaque tour commence ici`,"1gvmqkj":`Décision`,"2wk0tb":`Action`,ltbyq8:`oui`,r90oai:`non`,"10pfeta":`{file} · lignes {lines}`,"1mv69ab":`{file} · ligne {lines}`,v5glvz:`pas d’écho`,"1y6bn7c":`gauche {left} · droite {right}`,"17yvayv":`Voie libre : elle avance`,g8loky:`{reading} devant · s’arrête sous {stop} cm`,"1qpxp29":`Arrêt · LED allumée · bip`,lman68:`obstacle à {reading} · sous {stop} cm`,"4e4gg4":`A reculé : regarde autour`,"1x1kke3":`la mesure n’avait pas changé depuis {s} s`,"1pc4lzp":`A reculé : regarde à nouveau`,"11qad25":`les deux côtés étaient trop étroits pour tourner`,dfsfd7:`Coincée : elle recule`,eic5lt:`mesure inchangée pendant {s} s`,n7w5mt:`Pas la place de tourner : marche arrière`,etina8:`{sides} · sous {tight} cm`,crgp5w:`Regarde à droite`,vto9jk:`lit {reading}`,"1xubspn":`Regarde à gauche`,"92dcjq":`droite {right} · gauche lit {reading}`,cfs13v:`La place de tourner ?`,h7zzeh:`{sides} · il faut {tight} cm`,qlw2zr:`Tourne encore à gauche`,"1fd6gkc":`Tourne encore à droite`,"1hj21ci":`bloquée juste après un virage : même sens`,"1jk1kpr":`Tourne à gauche`,u6ps9c:`Tourne à droite`,"1uvg70v":`Auto est désactivé`,"1bbdvwo":`Vue en direct : voiture simulée uniquement`,"1fj8dwo":`passez en Auto pour voir la voiture décider`,"14g7i3l":`une vraie voiture transmet ses mesures, pas l’étape de sa routine`,"15nlm70":`Retour à l’étape {n} · {step}`,"1i8tm8j":`Monté à <b>cette étape</b>`,rpu2qi:`Monté à l’<b>étape {n} · {step}</b>`,"1b4o3fw":`Aller à l’étape {n} →`,y322vs:`Langue : {name}`,bk85tv:`Lecture`,"1x4eyna":`{action} (Espace)`,gpdo6z:`Utilisez une adresse ws:// ou wss://, par ex. ws://192.168.4.1:81/`,"1iquufv":`Rejoignez d’abord le réseau Wi-Fi de la voiture. Voir README.md pour le format des messages que le firmware doit parler.`,njqkz2:`Saisissez une URL WebSocket, par ex. ws://192.168.4.1:81/`,nrzvmi:`Conduit une voiture simulée dans une arène d’essai, sans matériel.`,cegybp:`Pièces`,wv4sck:`Préparation`,"7z3mbb":`Tout pour un rover à quatre roues avec une « tête » à ultrasons qui peut regarder autour d’elle. Disposez les pièces ainsi et cochez-les une à une. Survolez une ligne pour la trouver sur le tapis, ou cliquez sur une pièce pour ses détails.`,"1x97es5":`Chargez les cellules 18650 dans un vrai chargeur Li-ion avant de commencer, et utilisez des cellules protégées : une cellule non protégée peut débiter des dizaines d’ampères dans un court-circuit.`,"13wu8qd":`Châssis en acrylique : plateaux inférieur, du milieu et supérieur`,"9z9vwl":`Moteurs à réducteur TT (3–6 V, 1:48) avec 8 supports en acrylique en T, 8 boulons M3 × 30 et écrous`,"1qr4ely":`Roues, 65 mm`,cmzolq:`Module driver double moteur L9110S`,"1qgfn27":`Arduino UNO R3 + Sensor Shield V5 + câble USB`,"15cdntm":`ESP32 DevKit V1 (30 broches) + carte d’extension + câble USB`,mfnvxi:`Capteur à ultrasons HC-SR04 + son support pour servo et ses vis`,"15iavp3":`Micro servo SG90 avec palonniers et vis`,"1allzrf":`Cellules Li-ion 18650 (protégées) + support 2 places en série avec fils`,xooybo:`Interrupteur à glissière, LED rouge de 10 mm, résistance de 220 Ω, buzzer actif 5 V`,"1csc29i":`Interrupteur à glissière, LED rouge de 10 mm, buzzer actif 5 V, transistor NPN (PN2222A ou S8050), résistances de 220 Ω, 2 × 1 kΩ et 2 kΩ`,"17dpcif":`Fiche jack DC avec bornes à vis, 5.5 × 2.1 mm`,bozwcy:`20 câbles Dupont femelle–femelle de 15 cm ; fil de câblage rouge et noir ; 16 entretoises en laiton M3 femelle–femelle (8 × 25 mm, 4 × 15 mm, 4 × 10 mm), 32 vis M3 × 6 mm, ruban mousse, gaine thermorétractable`,"5z6ae7":`Fer à souder, soudure`,"1xhh6dp":`fils des moteurs, l’interrupteur, fils de la LED et du buzzer`,"11dguvz":`Petits tournevis`,"1b1pnob":`cruciforme pour les vis M3, plat pour les bornes du driver et de la fiche`,"1ligzav":`Pince coupante / pince à dénuder`,"3pb5yx":`couper et dénuder le fil de câblage et les câbles Dupont`,"1avt53n":`Multimètre`,"1slxnnr":`vérifier la polarité avant de mettre sous tension`,"100w2b7":`Chargeur Li-ion`,"64j96q":`pour les cellules 18650`,"1heknmc":`Ordinateur, Arduino IDE`,"1mo2nzj":`pour téléverser le code à l’étape 9`,t9gk37:`Moteurs`,"15i6udf":`Montage`,"1fofbt3":`Moteurs et roues`,"15llile":`Chaque moteur TT est un petit moteur DC qui entraîne un réducteur en plastique 1:48. Les deux moteurs de gauche et les deux de droite tournent toujours ensemble, comme les chenilles d’un char : la voiture tourne en faisant aller ses deux côtés à des vitesses différentes.`,k5fimq:`Le rouge sur la languette intérieure de chaque moteur est ce qui vous permet de relier rouge à rouge à l’étape 4 : le moteur avant et le moteur arrière d’un côté se font face, donc leurs languettes intérieures ont le même rôle. Les languettes sont fines et cassent si l’on tire sur un fil, alors scotchez chaque paire de fils à son moteur. Les fils restent dressés au centre pour que la longue fente du plateau du milieu puisse descendre par-dessus à l’étape 3.`,"7fte4n":`Plateau inférieur`,rbcm1a:`Moteurs à réducteur TT`,sjfn38:`Supports de moteur en acrylique en T`,"732lu":`Boulons M3 × 30 et écrous`,skq14t:`Roues`,"1s4rmq":`Posez les quatre moteurs à leur place sur le plateau inférieur, axes vers l’extérieur et extrémités des moteurs vers le centre. Soudez deux fils d’environ 15 cm sur chacun : le rouge sur la languette la plus proche du centre de la voiture, le noir sur celle la plus proche de la roue. Dressez les huit fils ensemble au centre du plateau.`,"1mrwedd":`Soulevez le plateau. Par en dessous, poussez un support à travers la fente du côté intérieur de chaque moteur et un autre dans l’encoche du bord du plateau, à l’extérieur. Passez deux boulons M3 × 30 à travers support, réducteur et support, têtes côté roue, et serrez un écrou sur chacun.`,"13sq8kw":`Enfoncez une roue sur chaque axe. L’axe a deux méplats qui s’emboîtent dans le moyeu, donc la roue ne peut pas patiner dessus.`,"199dyzl":`Plateaux`,qr73r6:`Empilez les plateaux`,kig8cy:`Les entretoises en laiton soulèvent le plateau du milieu de 25 mm au-dessus du plateau inférieur, au-dessus des réducteurs de 22 mm de haut, et donnent à l’électronique un plancher plat. Chaque entretoise est taraudée aux deux bouts : une vis monte à travers le plateau du dessous, une autre descend à travers ce qui est posé dessus.`,"1w8a39y":`L’acrylique se fend si on le serre trop : il suffit que ce soit ferme. Les châssis varient : si le vôtre n’a pas de trou là où le contrôleur en a besoin, deux entretoises et un coussinet de ruban mousse sous l’autre bout tiennent bien une carte.`,jcqip:`Plateau du milieu`,u6l9bq:`Entretoises en laiton M3 × 25 mm`,"4cdagt":`Entretoises en laiton M3 × 10 mm (pour le contrôleur)`,xaqs1y:`Entretoises en laiton M3 × 15 mm (pour le plateau supérieur)`,"300byl":`Vis M3 × 6 mm`,tezznv:`Vissez huit entretoises de 25 mm sur le plateau inférieur, quatre de chaque côté, chacune sur une vis passée par en dessous.`,"70hnlv":`Avant de poser le plateau du milieu, tant que vous pouvez encore passer dessous, fixez les quatre entretoises de 10 mm sous les trous de fixation du contrôleur (tenez la carte en place pour voir quels trous du plateau correspondent) et les quatre entretoises de 15 mm aux coins de sa moitié arrière, chacune avec une vis par en dessous.`,"1tynoxv":`Descendez le plateau du milieu sur les entretoises de 25 mm, en faisant passer les fils des moteurs par la longue fente centrale pendant qu’il descend, et vissez-le.`,"1n5adbz":`Driver`,"1ri406w":`Montez le driver des moteurs`,"5n5nar":`Une broche de microcontrôleur ne devrait pas fournir plus d’environ 20 mA, mais un moteur TT consomme quelques centaines de mA en roulant et plus de 1 A bloqué. Le module L9110S a deux ponts en H qui commutent le courant de la batterie à travers les moteurs et peuvent l’inverser.`,"1uicxnj":`Quelle vis d’un bornier reçoit quelle paire n’a pas encore d’importance : le test de câblage de l’étape 9 montre si un côté tourne à l’envers, ou si une roue tourne contre sa voisine. Laissez libre le connecteur 6 broches (B-IA, B-IB, GND, VCC, A-IA, A-IB) : l’alimentation arrive à l’étape 7 et les signaux à l’étape 8. Le L9110S supporte 800 mA par canal, et chaque canal pilote ici deux moteurs : suffisant pour rouler normalement, mais ne maintenez pas les roues bloquées. Si les puces chauffent, un module TB6612FNG (1.2 A par canal) est un remplacement plus robuste.`,utkklb:`Coussinet de ruban mousse double face`,syij08:`Collez le driver sur le plateau du milieu avec du ruban mousse, devant les entretoises du contrôleur et à gauche du centre : son connecteur 6 broches vers le bord gauche de la voiture, ses bornes à vis vers le centre de la voiture.`,"15kkcap":`Rabattez les fils vers l’avant le long du plateau et amenez-les aux bornes du driver. Torsadez ensemble les deux fils rouges des moteurs de gauche et ensemble leurs deux fils noirs, et vissez les deux paires dans MOTOR-A, le bornier le plus proche du contrôleur. Faites de même avec les fils des moteurs de droite dans MOTOR-B.`,"18rvg69":`Contrôleur`,ync8b9:`Montez l’Arduino UNO`,"1u68uls":`Montez l’ESP32`,ertyxs:`L’Arduino UNO (ATmega328P, 16 MHz, logique 5 V) exécute votre sketch. Un Sensor Shield V5 s’enfiche par-dessus et donne à chaque broche son propre connecteur G / V / S (masse, 5 V et signal), car le connecteur d’alimentation de l’UNO n’a qu’une broche 5 V à partager entre le servo et le capteur.`,"1p7bu2t":`L’ESP32 (double cœur, jusqu’à 240 MHz, Wi-Fi et Bluetooth, logique 3.3 V) exécute votre sketch et permet à RoboKit de piloter la vraie voiture en Wi-Fi. Sa carte d’extension ajoute une prise DC avec régulateur et un connecteur G / V / S pour chaque broche.`,ii2aq7:`Les broches de l’UNO sont en 5 V, donc le capteur et le servo se branchent directement sur le shield.`,"1ghuj2z":`Les broches de l’ESP32 fonctionnent en 3.3 V et ne tolèrent pas le 5 V, donc la sortie Echo du capteur reçoit un pont diviseur à l’étape 8.`,t5ws5g:`ESP32 DevKit V1 (30 broches)`,"1tu8qz5":`Carte d’extension ESP32 (30 broches)`,"14w4gx0":`Vissez l’UNO sur les quatre entretoises de 10 mm derrière le driver, ses prises USB et DC tournées vers le côté gauche de la voiture.`,hw767j:`Enfoncez le Sensor Shield V5 sur l’UNO avec chaque broche dans son support. Laissez le cavalier SEL en place, pour que les broches V du shield prennent le 5 V de l’UNO, et ne branchez rien sur le bornier à vis du shield.`,"1opbgrl":`Vissez la carte d’extension sur les quatre entretoises de 10 mm derrière le driver, sa prise DC tournée vers le côté gauche de la voiture.`,"1xxnsy2":`Installez le DevKit dans les deux supports de sorte que chaque nom de broche corresponde au nom imprimé à côté du support. Une carte décalée d’une broche met l’alimentation sur les mauvaises broches.`,ua2sfx:`Mettez le cavalier des broches V sur 5 V, car le servo, le HC-SR04 et le buzzer ont besoin de 5 V. Les cartes d’extension varient, alors vérifiez les marquages du cavalier sur la vôtre.`,"1jzloyj":`Capteur`,"19ot7f3":`Tête du capteur`,jii9ss:`Le HC-SR04 émet une salve ultrasonore à 40 kHz et chronomètre l’écho : distance en cm ≈ durée de l’écho en µs ÷ 58. Il mesure de 2 cm à environ 4 m dans un faisceau d’environ 15° de large. Monté sur un servo SG90, il peut regarder à gauche et à droite avant que la voiture tourne.`,"1s5nsw8":`Pour centrer le servo, branchez-le sur le connecteur A5 du shield (marron sur G) et téléversez l’un des sketches de l’étape 9 : tous deux laissent la tête à 90°. Tourner l’axe de sortie de force peut abîmer ses engrenages en plastique. Monté dans ce sens, les broches du capteur sont GND, Echo, Trig, VCC de gauche à droite, vues de face.`,"3b6msg":`Pour centrer le servo, branchez-le sur le connecteur GPIO 23 (marron sur G, V réglé sur 5 V) et téléversez le firmware de l’étape 9, dont le setup() appelle servoWrite(90). Tourner l’axe de sortie de force peut abîmer ses engrenages en plastique. Monté dans ce sens, les broches du capteur sont GND, Echo, Trig, VCC de gauche à droite, vues de face.`,"2934zx":`Micro servo SG90, palonnier simple et vis`,"1o4q0ha":`Support de servo pour le HC-SR04, avec ses vis`,"87cfw2":`Capteur à ultrasons HC-SR04`,"1bhe6w2":`Tenez le servo au-dessus de la découpe rectangulaire à l’avant du plateau du milieu, axe de sortie vers le haut et sur l’axe central de la voiture. Faites passer sa fiche vers le bas par la découpe, vers l’arrière sous le plateau et vers le haut par la petite fente derrière, et tirez le câble jusqu’à ce que la fiche repose sur le plateau à côté du contrôleur. Puis descendez le servo dans la découpe, le câble passant par l’encoche à son bout, repoussez le surplus de câble sous le plateau, loin de l’axe du moteur, et vissez les deux oreilles du servo sur le plateau.`,"7x26fs":`Centrez le servo, puis enfoncez un palonnier simple sur son axe, pointé vers l’avant, et fixez-le avec la vis du palonnier.`,"3f8bcm":`Vissez le support sur le palonnier, droit, vers l’avant.`,"178kb38":`Vissez le HC-SR04 à l’avant du support par les deux trous d’angle d’un grand côté, ce côté en bas et les broches en haut : ses fils partent alors vers le haut, loin du servo.`,"1jamndy":`Alimentation`,tboesy:`Deux cellules 18650 en série donnent 7.4 V nominaux (8.4 V chargées, environ 6 V vides). L’interrupteur coupe le fil + de la batterie. Tout se rejoint sur une fiche DC à bornes à vis : les deux fils de la batterie y entrent, la fiche alimente l’UNO par sa prise DC, dont le régulateur produit le 5 V de la logique, et deux autres fils partant des mêmes bornes alimentent le driver des moteurs. Le driver ne peut pas prendre son alimentation sur les broches 5 V du shield : elles viennent du petit régulateur de l’UNO, que quatre moteurs surchargeraient. Les pièces qui ont besoin de fils soudés les reçoivent à l’établi, avant d’aller sur la voiture : enfilez d’abord un bout de gaine thermorétractable sur le fil, puis rétractez-le sur la soudure ensuite.`,r69l9i:`Deux cellules 18650 en série donnent 7.4 V nominaux (8.4 V chargées, environ 6 V vides). L’interrupteur coupe le fil + de la batterie. Tout se rejoint sur une fiche DC à bornes à vis : les deux fils de la batterie y entrent, la fiche alimente la carte d’extension par sa prise DC, dont les régulateurs produisent le 5 V et le 3.3 V de la logique, et deux autres fils partant des mêmes bornes alimentent le driver des moteurs. Le driver ne peut pas prendre son alimentation sur les broches 5 V de la carte : elles viennent de son petit régulateur, que quatre moteurs surchargeraient. Les pièces qui ont besoin de fils soudés les reçoivent à l’établi, avant d’aller sur la voiture : enfilez d’abord un bout de gaine thermorétractable sur le fil, puis rétractez-le sur la soudure ensuite.`,"175zcey":`Vérifiez deux fois la polarité avant d’insérer les cellules : la prise de l’UNO a le plus au centre, et la borne + de la fiche est sa broche centrale (vérifiez au multimètre). Rechargez quand le pack descend vers 7 V, en dessous de quoi le régulateur de l’UNO ne tient plus 5 V. Si aucune LED ne s’allume, coupez tout de suite et vérifiez le câblage avant de réessayer. La LED et le buzzer restent à l’établi jusqu’à l’étape 8.`,t60ux3:`Vérifiez deux fois la polarité avant d’insérer les cellules : la plupart des cartes d’extension ont le plus au centre, mais vérifiez le symbole près de la prise, et la borne + de la fiche est sa broche centrale (vérifiez au multimètre). Rechargez quand le pack descend vers 7 V. Si aucune LED ne s’allume, coupez tout de suite et vérifiez le câblage avant de réessayer. La LED et le buzzer restent à l’établi jusqu’à l’étape 8.`,mvli44:`Plateau supérieur + 4 vis M3 × 6 mm`,"1dowjmo":`Support 2 × 18650 avec fils, 2 cellules`,"83x4u2":`Interrupteur à glissière`,"1in9b4e":`Fiche jack DC avec bornes à vis (centre +)`,l8wrh1:`LED rouge de 10 mm + résistance de 220 Ω`,"24gtky":`Buzzer actif 5 V`,"14zuroc":`Buzzer actif 5 V, transistor NPN + résistance de 1 kΩ`,"1pgj6ai":`Ruban mousse, gaine thermorétractable, 4 câbles Dupont à couper : 2 rouges, 2 noirs`,"1ewjpxi":`Ruban mousse, gaine thermorétractable, 5 câbles Dupont à couper : 2 rouges, 2 noirs, 1 orange`,y2bs3a:`Posez le plateau supérieur sur les quatre entretoises de 15 mm et vissez-le.`,anc24f:`À l’établi, coupez le fil rouge du support de piles à environ 2 cm du support. Soudez le bout côté support à une broche extérieure de l’interrupteur, et 10 cm du morceau coupé à la broche du milieu.`,"1mixan6":`Tenez le support au-dessus du plateau supérieur, ses fils vers la gauche de la voiture. Passez le fil noir vers le bas par le trou du bord gauche du plateau et amenez-le vers l’avant le long du plateau du milieu pendant que vous descendez le support. Collez le support avec deux bandes de ruban mousse, et l’interrupteur sur le flanc au bord gauche du plateau, levier vers l’extérieur. Puis amenez le fil rouge vers l’avant, par le coin avant du plateau. Les deux fils doivent finir à côté de la prise DC du contrôleur.`,"1xim7b6":`Coupez un câble Dupont rouge et un noir à 12.5 cm d’un bout. Enfoncez la fiche du long morceau rouge sur la broche VCC du driver et celle du long noir sur GND, et ramenez-les le long du bord gauche du plateau du milieu jusqu’à la prise.`,"1200i":`Coupez un câble Dupont rouge et un noir à 11 cm d’un bout. Enfoncez la fiche du long morceau rouge sur la broche VCC du driver et celle du long noir sur GND, et ramenez-les le long du bord gauche du plateau du milieu jusqu’à la prise.`,"1nymzxl":`Dénudez 5 mm aux quatre bouts libres. Vissez les deux rouges sous la vis + de la fiche et les deux noirs sous la −, puis enfoncez la fiche dans la prise DC de l’UNO, tournée pour que le + soit en haut.`,f3jc5e:`Dénudez 5 mm aux quatre bouts libres. Vissez les deux rouges sous la vis + de la fiche et les deux noirs sous la −, puis enfoncez la fiche dans la prise DC de la carte d’extension, tournée pour que le + soit en haut.`,hhvzfi:`À l’établi, soudez la résistance de 220 Ω en série avec la longue patte (+) de la LED. Coupez en deux un câble Dupont rouge et un noir. Soudez une moitié rouge au bout libre de la résistance et une moitié noire à la courte patte de la LED.`,"1qz1083":`Pliez à plat les deux broches du buzzer. Soudez l’autre moitié rouge au + (la broche la plus longue, marquée sur le dessus) et l’autre moitié noire au −.`,"110bbxt":`Pliez à plat les deux broches du buzzer et soudez l’autre moitié rouge au + (la broche la plus longue, marquée sur le dessus). Soudez le collecteur du transistor à la broche − et une résistance de 1 kΩ à sa base, puis une moitié de câble orange à la résistance et l’autre moitié noire à l’émetteur. Rétractez une seule gaine sur le transistor et la résistance. Vérifiez quelle patte est laquelle dans la fiche technique de votre transistor.`,"1avlub7":`Vérifiez qu’aucune soudure nue ne peut en toucher une autre et que l’interrupteur est coupé. Puis mettez les deux cellules dans le support, chaque bout + là où le support indique +. Allumez un instant : les LED d’alimentation du contrôleur et du driver doivent toutes deux s’allumer.`,k2hc2b:`Câblage`,s234wa:`Câblez la voiture`,"1po8toc":`Chaque capteur et actionneur se branche sur un connecteur G / V / S du shield, ils partagent donc tous la masse de l’UNO ; la masse du driver vient de la batterie, qui est la même masse via la prise DC. Les broches sont choisies selon la place de chaque pièce, donc les fils partent en éventail des connecteurs sans se croiser. Travaillez dans cet ordre, interrupteur coupé : d’abord la LED, en bas au bout gauche du connecteur, et les quatre fils du capteur en dernier, car ils passent en arc par-dessus tout le reste. Un câble Dupont se met un bout à la fois : enfoncez bien une fiche sur sa broche, repliez le fil, enfoncez l’autre. Survolez une ligne pour voir le fil sur le modèle.`,"1ylwoyd":`Chaque capteur et actionneur se branche sur un connecteur G / V / S de la carte d’extension, ils partagent donc tous la masse de l’ESP32 ; la masse du driver vient de la batterie, qui est la même masse via la prise DC. Les broches sont choisies selon la place de chaque pièce, donc les fils partent en éventail des connecteurs sans se croiser. Travaillez dans cet ordre, interrupteur coupé : d’abord la LED, en bas au bout gauche du connecteur, et les fils du capteur en dernier, car ils passent en arc par-dessus tout le reste. Un câble Dupont se met un bout à la fois : enfoncez bien une fiche sur sa broche, repliez le fil, enfoncez l’autre. Survolez une ligne pour voir le fil sur le modèle.`,"10tvb2g":`D5 et D11 portent la vitesse de chaque côté : ce sont des broches PWM qui continuent de fonctionner pendant que la bibliothèque Servo tourne (elle prend le Timer1, ce qui coupe le PWM sur D9 et D10). D6 et D12 portent le sens. Le servo et le buzzer utilisent A5 et A0 comme broches numériques ordinaires. Toutes les broches G sont reliées, et toutes les broches V aussi : le GND et le VCC du capteur peuvent aller sur les plus proches.`,it0an4:`Le pont diviseur 1 kΩ / 2 kΩ transforme l’impulsion Echo de 5 V en 3.3 V (5 V × 2 ⁄ 3). Echo utilise le GPIO 35, l’une des broches en entrée seule (34–39) : lire est tout ce qu’elle a à faire. Le buzzer est alimenté par la broche V en 5 V et le transistor le commute, car 3.3 V est en dessous de ce dont un buzzer 5 V a besoin. Les sorties évitent les GPIO 0, 2, 5, 12, 14 et 15, qui sont des broches de démarrage ou émettent des impulsions pendant le démarrage de l’ESP32. Toutes les broches G sont reliées, et toutes les broches V aussi.`,"16ffufp":`LED : collez-la près du coin avant gauche du contrôleur · rouge → S · noir → G`,"55vkwv":`Driver A-IA / A-IB (gauche)`,"1wr2rcy":`Driver B-IA / B-IB (droite)`,"12y58k1":`Câble du servo (marron G, rouge V, orange S)`,"1xjcvwz":`Buzzer : collez-le à l’avant du plateau supérieur · rouge → S · noir → G`,"1h6hx3u":`HC-SR04 Trig → S · VCC → V · GND → G de D2`,zvbj2f:`HC-SR04 Echo`,"83uabx":`Buzzer : collez-le à l’avant du plateau supérieur · rouge → V · orange (base) → S · noir (émetteur) → G`,"1eb7xia":`HC-SR04 Trig → S · VCC → V · GND → G de GPIO 34`,"1ig2p4r":`HC-SR04 Echo : coupez son câble à 4.5 cm d’un bout · 1 kΩ entre les morceaux · 2 kΩ vers 4.7 cm coupés au bout d’un câble noir · morceaux courts → S et G`,xoaiok:`Code`,"1if8prf":`Programmation`,"1g03ums":`Téléversez le code`,"1bv2ey7":`Deux sketches. Le test de câblage passe chaque pièce en revue, pour que vous voyiez que chacune est branchée et que les deux côtés tournent dans le bon sens. L’évitement d’obstacles est le programme de la voiture : elle roule jusqu’à ce que quelque chose soit à moins de 22 cm, regarde à droite et à gauche avec la tête, et tourne vers le côté le plus dégagé.`,"8lzj5q":`Ce firmware fait de l’ESP32 un point d’accès Wi-Fi. Il exécute les commandes que RoboKit envoie (conduite, vitesse, mode, servo, LED et buzzer), s’arrête si elles cessent d’arriver, et renvoie la distance et l’état des moteurs 10 fois par seconde. En mode Auto il évite les obstacles tout seul, avec la même routine que celle du simulateur.`,saufbh:`Quand rien ne renvoie le ping, le HC-SR04 maintient Echo à l’état haut environ 38 ms (le chiffre de la fiche technique ; certains modules le maintiennent plus longtemps). Cela dépasse le délai de 30 ms, donc pulseIn() renvoie 0. Le programme compte cela comme 400 cm, « libre », et non comme « au contact ». Son faisceau est étroit, donc la voiture peut accrocher un coin qu’elle n’a jamais vu : une mesure qui cesse de changer alors que les roues poussent lui indique qu’elle est coincée. Et quand elle est bloquée à nouveau juste après un virage, elle tourne encore une fois dans le même sens au lieu de revenir : dans un coin, sinon, elle tournerait à gauche, à droite, à gauche sans fin.`,"11hew0t":`ledcAttach() et ledcWrite(pin, duty) sont l’API d’arduino-esp32 3.x ; les anciens appels ledcSetup() et ledcAttachPin() de la 2.x ne compilent plus. Le faisceau du capteur est étroit, donc en Auto la voiture peut accrocher un coin qu’elle n’a jamais vu : une mesure qui cesse de changer alors que les roues poussent lui indique qu’elle est coincée. Et quand elle est bloquée à nouveau juste après un virage, elle tourne encore une fois dans le même sens au lieu de revenir : dans un coin, sinon, elle tournerait à gauche, à droite, à gauche sans fin.`,"3zk06m":`Dans l’Arduino IDE, choisissez Tools → Board → Arduino UNO et le bon port. Les deux sketches utilisent la bibliothèque Servo, fournie avec l’IDE.`,j0z2nr:`Surélevez la voiture pour que les quatre roues ne touchent pas la table. Téléversez le test de câblage, allumez la batterie et ouvrez le Serial Monitor à 115200 bauds. Regardez chaque ligne numérotée se produire : LED et bip, tête à droite, à gauche et au centre, puis chaque côté en avant et en arrière.`,"1dz2oap":`Corrigez ce qui ne correspondait pas (voir la liste ci-dessous). Puis téléversez l’évitement d’obstacles, débranchez le câble USB, posez la voiture par terre et allumez : elle attend deux secondes, puis démarre.`,"4czqhs":`Modifiez TURN_MS dans le sketch jusqu’à ce que chaque virage fasse environ un quart de tour sur votre sol.`,rgjhux:`Dans l’Arduino IDE, ajoutez https://espressif.github.io/arduino-esp32/package_esp32_index.json sous File → Preferences → Additional boards manager URLs. Installez ensuite « esp32 by Espressif Systems » version 3.x depuis le Boards Manager et choisissez ESP32 Dev Module.`,"118rr9r":`Depuis le Library Manager, installez la dernière « WebSockets » de Markus Sattler et « ArduinoJson » version 7 de Benoit Blanchon.`,nbb8bl:`Téléversez, puis surélevez la voiture pour que les quatre roues ne touchent pas la table et allumez la batterie. Rejoignez le réseau Wi-Fi « RoboKit » (mot de passe drive1234), allez à l’étape 10 et connectez-vous depuis Réglages → Vraie voiture (Wi-Fi de l’ESP32).`,srtywe:`Essayez chaque commande tour à tour : LED, buzzer, le curseur du servo, puis W A S D. Si un côté tourne dans le mauvais sens, voyez la liste ci-dessous. Puis posez la voiture par terre, essayez Auto et modifiez TURN_MS jusqu’à ce que chaque virage fasse environ un quart de tour.`,sp50jr:`Rien ne s’allume à la mise sous tension`,"1gg4m0p":`Coupez. Vérifiez que les cellules sont chargées et dans le bon sens, que les fils rouges sont sous la vis + de la fiche, et que l’interrupteur est câblé entre sa broche du milieu et une broche extérieure.`,"9crnd5":`Un côté tourne à l’envers pendant le test`,"1mf4jfi":`Inversez les deux fils de ce côté dans son bornier à vis : MOTOR-A est le côté gauche, MOTOR-B le droit.`,"1gcvytv":`Une roue tourne contre sa voisine`,"76bppn":`Inversez les deux fils de ce moteur là où ils sont torsadés avec ceux de l’autre moteur.`,kakgt9:`La ligne 3 fait tourner les roues de droite`,"95tfvz":`Les deux paires de câbles sont croisées : A-IA / A-IB vont sur D11 / D12, B-IA / B-IB sur D5 / D6.`,"1yvpqg9":`La tête regarde d’abord à gauche`,"3fc0ov":`Certains servos tournent dans l’autre sens : échangez 20 et 160 dans les sketches.`,"1ymivbo":`La distance vaut toujours 0.0 cm`,"1wzcqly":`Aucun écho ne revient. Vérifiez que Trig est sur D4 et Echo sur D3, et que le VCC et le GND du capteur sont sur une broche V et une broche G. Il lit aussi 0 quand rien n’est à moins d’environ 4 m.`,lg1f33:`L’UNO redémarre quand les moteurs démarrent`,gp3cr0:`La tension de la batterie chute : rechargez les cellules. Un condensateur de 470–1000 µF entre V et G sur le shield (attention à sa polarité) aide l’alimentation 5 V à passer les creux.`,"13n04wo":`La voiture ronronne mais ne tourne pas sur place`,y7q52i:`Tourner fait frotter les quatre pneus de côté et demande plus de force que rouler droit : augmentez SPIN vers MAX_PWM et rechargez les cellules.`,hvphiw:`Elle dérive d’un côté`,ittf4s:`Aucun moteur n’est identique à un autre. Ralentissez le côté le plus rapide : pour une voiture qui dérive à droite, drive(CRUISE - 10, CRUISE).`,"19do8xl":`Le téléversement s’arrête à « Connecting… »`,hn5crr:`Maintenez le bouton BOOT du DevKit jusqu’au début du téléversement, et vérifiez que le câble USB transmet des données, pas seulement du courant.`,"144ggw6":`RoboKit ne se connecte pas`,"1wm6oj5":`Un côté tourne à l’envers`,"1buhj6h":`La gauche et la droite sont inversées`,"1s6olzj":`Les deux paires de câbles sont croisées : A-IA / A-IB vont sur GPIO 26 / 27, B-IA / B-IB sur GPIO 33 / 25.`,svln7p:`En Auto, la tête regarde d’abord à gauche`,"1ki0m9i":`Certains servos tournent dans l’autre sens : échangez 20 et 160 dans autoStep().`,"6xg3a":`La distance vaut toujours 400 cm`,"7himiv":`Aucun écho ne revient. Vérifiez que Trig est sur GPIO 32, qu’Echo atteint GPIO 35 à travers le pont diviseur, et que le VCC du capteur est sur une broche 5 V. Il lit aussi 400 quand rien n’est à moins d’environ 4 m.`,ksb87p:`Le buzzer reste muet`,"9czfii":`Vérifiez les pattes du transistor d’après sa fiche technique (l’ordre change selon le type), et que le + du buzzer est sur une broche 5 V.`,igpqu0:`L’ESP32 redémarre quand les moteurs démarrent`,owaty5:`La tension de la batterie chute : rechargez les cellules. Un condensateur de 470–1000 µF entre une broche 5 V et G (attention à sa polarité) aide l’alimentation à passer les creux.`,"1u5gnnb":`Tourner fait frotter les quatre pneus de côté et demande plus de force que rouler droit : augmentez la vitesse et rechargez les cellules.`,uak3xr:`1 · Test de câblage`,"1jz093b":`2 · Évitement d’obstacles`,"129dlzg":`Firmware`,ussxe7:`Simulation`,"17ssthc":`Conduisez-la`,bmzqy4:`La voiture simulée a les mêmes pièces que la vôtre. Conduisez-la dans l’arène d’essai, puis passez en Auto : elle exécute la même routine que le sketch d’évitement d’obstacles. Elle s’arrête et bipe devant un obstacle, regarde à droite et à gauche, tourne vers le côté le plus dégagé, et recule quand elle est coincée.`,"189d210":`La voiture simulée répond aux mêmes commandes que RoboKit envoie à votre ESP32, et Auto exécute la même routine que le firmware. Une fois votre voiture construite, passez-y dans Réglages → Vraie voiture (Wi-Fi de l’ESP32).`,olmdkx:`Roue, 65 mm`,psly3z:`Transmission`,vffqvh:`Un pneu en caoutchouc sur une jante en plastique. Son moyeu a un logement à deux méplats qui s’enfonce sur l’axe de sortie du moteur TT, donc la roue ne peut pas patiner. Quand la voiture tourne sur place, les pneus frottent de côté : l’adhérence compte.`,jq4v4c:`Moyeu`,mq93xq:`logement à double méplat pour l’axe du moteur TT`,"1cgpuek":`Distance par tour`,esl998:`≈ 20.4 cm (π × 6.5 cm)`,"11yszgp":`Moteur à réducteur TT`,m5llum:`Un petit moteur DC à balais qui entraîne un réducteur en plastique 1:48. Inversez le courant et la roue tourne dans l’autre sens ; baissez la tension moyenne avec du PWM et elle ralentit.`,"525amd":`Tension`,"226us9":`Rapport de réduction`,jpnnsq:`≈ 200 tr/min à 6 V, à vide`,"1dw4k8q":`Courant`,"1p9wnb6":`≈ 150 mA à vide · jusqu’à ≈ 1.5 A bloqué à 6 V`,cdauuh:`Couple de blocage`,"1gzxf67":`≈ 0.8 kg·cm à 6 V`,ign4wl:`Corps`,mad9cv:`Axe`,"14e36jb":`Ø 5.5 mm avec deux méplats espacés de 3.7 mm, sortant des deux côtés`,feutd2:`Fixation`,"183nrmx":`deux trous de Ø 3 mm espacés de 17.5 mm, à 20 mm derrière l’axe`,"108seeu":`Support de moteur`,"1mquwkf":`Châssis`,"10qeeg1":`Une pièce d’acrylique en forme de T. Sa tige remonte à travers le plateau inférieur à côté du réducteur et sa tête reste dessous, donc elle ne peut pas passer à travers. Il y en a un de chaque côté d’un moteur, et deux longs boulons traversent les deux supports et les deux trous de fixation du réducteur.`,"1kk17cw":`Matériau`,"1me4wyg":`acrylique`,st0e1p:`Par moteur`,"8uzq1j":`2 supports · 2 × boulons M3 × 30 + écrous`,"1am47c9":`Montage`,v6cwyh:`par-dessous le plateau : l’intérieur dans une fente, l’extérieur dans une encoche du bord`,"723pu9":`Porte les quatre moteurs et les huit entretoises du plateau du milieu. Une fente et une encoche au bord, à côté de chaque moteur, reçoivent les deux supports de ce moteur.`,"1n7meho":`Taille (ce modèle)`,r4lxco:`Le plancher de l’électronique. La longue fente au centre laisse monter les fils des moteurs par-dessous, et la découpe rectangulaire à l’avant tient le servo ; l’encoche à son bout est pour le câble du servo.`,"11vqw8c":`25 mm au-dessus du plateau inférieur`,"1957t19":`Plateau supérieur`,"2ljc6y":`Un demi-plateau à l’arrière qui porte le pack de batteries, l’interrupteur et le buzzer au-dessus de l’électronique.`,"1ytak7b":`1.5 cm au-dessus du plateau du milieu`,"1ey525v":`Entretoise en laiton, M3`,"7je4w9":`Entretoises hexagonales taraudées aux deux bouts. Elles écartent les plateaux et surélèvent les cartes électroniques au-dessus de l’acrylique pour que rien ne touche dessous.`,"1t2znv5":`Filetage`,i9dhsi:`M3, femelle–femelle`,"1cazjzs":`plateau inférieur → du milieu (passe au-dessus des moteurs de 22 mm)`,rni6ay:`plateau du milieu → supérieur`,"1dz3bjd":`carte du contrôleur`,"1erre2c":`Vis`,"7fsd49":`une M3 × 6 mm à chaque bout, 32 en tout`,pmsrct:`Fils des moteurs`,h0ivdz:`Un fil rouge et un noir par moteur : le rouge sur la languette la plus proche du centre de la voiture, le noir sur celle la plus proche de la roue. Les deux moteurs de chaque côté sont câblés en parallèle sur un canal du driver, rouge avec rouge et noir avec noir, donc ils tournent toujours ensemble.`,"148isqp":`environ 15 cm chacun`,"88dh10":`Paire de gauche`,"1hr3y9w":`MOTOR-A`,"1gp3zrj":`Paire de droite`,"1il2rct":`MOTOR-B`,"4iibl6":`Un côté tourne à l’envers ?`,"1p9lbgb":`inversez ses deux paires dans le bornier`,"2380z5":`Une roue contre sa voisine ?`,h5sbfv:`inversez les deux fils de ce moteur`,"19qn9l6":`Driver de moteurs L9110S`,"82whm4":`Électronique`,"12ibf8u":`Deux puces pont en H L9110S, une par canal. Chaque canal a deux entrées : IA haut et IB bas fait tourner le moteur dans un sens, IA bas et IB haut dans l’autre, et les deux identiques l’arrêtent. Du PWM sur une entrée règle la vitesse.`,"25ul91":`Alimentation (VCC)`,m2phlf:`800 mA par canal (1.5–2 A en crête)`,"17s6ks8":`Entrées`,d0m2ee:`A-IA, A-IB, B-IA, B-IB · logique 3.3 V ou 5 V`,"4swwow":`Connecteur`,oja0mi:`B-IA · B-IB · GND · VCC · A-IA · A-IB (broches coudées)`,"1xbblqt":`environ 29 × 23 mm, trous de fixation de Ø 3 mm (les dimensions varient selon le vendeur)`,"189a81e":`Une carte à microcontrôleur ATmega328P. Elle exécute votre sketch, lit le capteur et décide de ce que font les moteurs.`,"1ebaepz":`ATmega328P à 16 MHz`,"16qkmtv":`Niveau logique`,eslzkd:`Broches PWM`,oopaku:`Mémoire`,"8hfwsd":`32 KB de flash · 2 KB de RAM`,"1jzh7y5":`Alimentation d’entrée`,"1vbs2jm":`7–12 V sur la prise DC (recommandé)`,"1hxwxrt":`Courant par broche`,xms582:`20 mA recommandés · 40 mA maximum absolu`,"1n28mf4":`S’enfiche sur l’UNO et amène chaque broche sur un connecteur 3 broches G / V / S (masse, 5 V, signal), pour qu’un servo ou un capteur s’y branche directement avec sa propre masse et son alimentation.`,e8ir2h:`Connecteurs`,d0uaj4:`D0–D13 et A0–A5, chacun G · V · S`,"1iy90zn":`Broches V`,ohp32m:`5 V de l’UNO tant que le cavalier SEL est en place`,"1y4aysj":`Sans le cavalier`,gi4ocs:`V vient du bornier à vis du shield`,"1thlwjq":`Attention`,"1fzsig9":`n’alimentez jamais le bornier à vis avec SEL en place`,"1kft85q":`Extras`,"1e4238k":`Connecteurs I²C et série`,"1jeelmn":`ESP32 DevKit + carte d’extension`,"8jd2d6":`Un microcontrôleur double cœur avec Wi-Fi et Bluetooth, posé sur une carte d’extension qui ajoute une prise DC avec régulateur et un connecteur G / V / S pour chaque broche.`,"1inmx8d":`Module`,qx458t:`ESP32-WROOM-32 · jusqu’à 240 MHz`,"7ra2ga":`3.3 V, ne tolère pas le 5 V`,"1chl2hi":`n’importe quelle broche de sortie (LEDC)`,"7fk3dd":`Sans fil`,"1b7zmuj":`Wi-Fi 802.11 b/g/n · Bluetooth`,pawwts:`≈ 6.5–12 V sur la prise DC (vérifiez votre carte)`,yzyhje:`3.3 V ou 5 V, selon un cavalier`,"7wntef":`Micro servo SG90`,mni0ct:`Un petit moteur, un réducteur et un capteur de position dans un même boîtier. Il attend une impulsion toutes les 20 ms (50 Hz) ; la largeur de l’impulsion fixe l’angle : 1.5 ms est le centre, et environ 0.5–2.4 ms couvrent de 0° à 180°.`,wvoosj:`Couple`,"1e13gca":`≈ 0.1 s pour 60°`,"1yo9wk7":`Taille · masse`,"1oaes5p":`23 × 12 × 29 mm · 9 g`,"1b34x3l":`Fils`,"1qalf36":`marron GND · rouge V+ · orange signal`,"1bshntj":`Support de servo du HC-SR04`,"1yr5sge":`Se visse sur le palonnier du servo et tient le HC-SR04 par deux de ses trous d’angle, donc le capteur tourne avec le servo et son faisceau reste horizontal.`,"1t4m9bk":`Fixation`,mnle4w:`vis du palonnier`,"1yzxd81":`Tient`,"1fp9bdu":`le HC-SR04 par deux de ses trous d’angle, sur entretoises`,"1yozvc2":`Autres modèles`,"16fhes5":`beaucoup de supports tiennent plutôt le capteur par ses deux transducteurs`,c8gdr7:`Une impulsion de 10 µs sur Trig fait émettre à un transducteur huit cycles à 40 kHz ; l’autre écoute. Echo reste ensuite à l’état haut le temps que le son a mis pour aller et revenir, donc cm = µs ÷ 58 (343 m/s, divisé par deux).`,"198uyr6":`Portée`,"3xsn4q":`Faisceau`,"1gw4v0v":`moins de 15°`,"1oy2zwu":`Alimentation`,"1m7niep":`Cadence des pings`,"7gsn1j":`un toutes les 60 ms ou moins souvent`,npm5w4:`Broches (face, gauche → droite)`,pyp646:`VCC · Trig · Echo · GND broches en bas ; monté broches en haut, comme ici : GND · Echo · Trig · VCC`,cr1wqh:`Pack Li-ion 2 × 18650`,"1fdnj4z":`Deux cellules en série : 8.4 V chargées, 7.4 V nominaux, environ 6 V vides. Utilisez des cellules protégées, ne les court-circuitez jamais, et chargez-les dans un vrai chargeur Li-ion.`,w63ube:`7.4 V nominaux (6–8.4 V)`,serueh:`Capacité`,"1lup9sh":`2000–3500 mAh (cellules authentiques)`,"7l22en":`Support`,"1ka7i4l":`2 places, en série`,"1h1ba5m":`les cellules protégées sont quelques mm plus longues ; vérifiez qu’elles rentrent`,h4px5m:`Interrupteur`,bs7ocz:`Coupe le fil + de la batterie, donc toute la voiture est éteinte. Il est câblé entre sa broche du milieu et une broche extérieure : le fil rouge du support sur l’une, le fil vers la fiche sur l’autre. Il est posé sur le flanc sur du ruban mousse au bord gauche du plateau supérieur, levier vers l’extérieur, à portée de doigt.`,"1m2zofh":`Type`,"69jc9h":`interrupteur à glissière SPDT utilisé en marche/arrêt`,w3vkqt:`Broches`,"1owufyi":`trois en ligne : extérieure · commun · extérieure`,fph5dc:`Calibre`,"1bpycfc":`choisissez-en un prévu pour ≥ 2 A DC`,k3s7zg:`Buzzer actif, 5 V`,"177ed2m":`Signalisation`,jfbt4g:`Il a son propre oscillateur intégré : mettez la broche à HIGH et il bipe à une hauteur fixe, sans code tone(). Il consomme jusqu’à environ 25–30 mA : dans le maximum absolu de 40 mA de la broche mais au-dessus des 20 mA habituellement recommandés, donc le commuter avec un transistor NPN est l’habitude la plus douce.`,xscire:`Il a son propre oscillateur intégré : alimentez-le et il bipe à une hauteur fixe. Les buzzers actifs 5 V sont prévus à partir d’environ 3.5–4 V, donc une broche 3.3 V ne peut pas en faire fonctionner un de façon fiable. Ici il est alimenté par la broche V en 5 V et un transistor NPN, commandé par le GPIO 21, le commute.`,"1p7q9i9":`Tonalité`,"17n9x61":`≈ 2.3 kHz`,z19kz7:`Tension nominale`,"2tl42a":`5 V (fonctionne à partir de ≈ 3.5–4 V, selon le fabricant)`,"1udh5u4":`≈ 25–30 mA à 5 V`,"1xat3vm":`espacées de 7.6 mm`,"1yzktex":`Polarité`,"1tmcwg9":`broche la plus longue / « + » sur le dessus = +`,i8lb7k:`LED rouge de 10 mm`,"513nhj":`Le courant va de la longue patte (anode, +) à la courte (cathode, −, côté méplat du bord). Elle a toujours besoin d’une résistance en série. Ici elle est posée sur le flanc près du coin avant gauche du contrôleur, éclairant vers la gauche de la voiture.`,"17jikfo":`Tension directe`,"1g61wql":`20 mA max`,u532rf:`Résistance de 220 Ω`,"17qhgqf":`Limite le courant de la LED : (5 V − 2 V) ÷ 220 Ω ≈ 14 mA. Les anneaux de couleur se lisent rouge, rouge, marron : 2, 2 et × 10 = 220 Ω.`,"1kwszon":`Limite le courant de la LED : (3.3 V − 2 V) ÷ 220 Ω ≈ 6 mA. Les anneaux de couleur se lisent rouge, rouge, marron : 2, 2 et × 10 = 220 Ω.`,zzpczz:`Anneaux`,"7ytjo4":`rouge · rouge · marron · or`,"1llx3uw":`Tolérance`,"3389ey":`Diviseur d’Echo · 1 kΩ + 2 kΩ`,i8pnlw:`La sortie Echo du HC-SR04 monte à 5 V, mais les broches de l’ESP32 acceptent au plus 3.3 V. Deux résistances en série d’Echo à la masse forment un pont diviseur : le GPIO lit la tension aux bornes de celle de 2 kΩ, 5 V × 2 kΩ ÷ (1 kΩ + 2 kΩ) ≈ 3.3 V.`,"15yc2v4":`Anneaux de 1 kΩ`,"89urq0":`marron · noir · rouge · or`,"1ypqwgn":`Anneaux de 2 kΩ`,"1ywrkmt":`rouge · noir · rouge · or`,"12k1o0e":`Echo → 1 kΩ → GPIO 35 · 2 kΩ de GPIO 35 à G`,aarp77:`Nécessaire pour`,"15e8vss":`ESP32 seulement`,"1aqlq1n":`Transistor du buzzer · NPN + 1 kΩ`,vudz42:`Un transistor NPN fonctionne comme un interrupteur : un petit courant dans sa base laisse passer un courant plus fort du collecteur à l’émetteur. Le GPIO 21 commande la base à travers 1 kΩ, (3.3 V − 0.7 V) ÷ 1 kΩ ≈ 2.6 mA, largement assez pour commuter les ≈ 30 mA du buzzer depuis la broche 5 V.`,"1gy1kba":`Transistor`,"62rwh2":`PN2222A, S8050 ou un NPN similaire`,"1tlwyig":`Collecteur`,"18vf2cp":`− du buzzer`,"19phq7s":`Base`,hrttng:`1 kΩ → S de GPIO 21`,"10ztoj1":`Émetteur`,"1m0unsb":`G de GPIO 21`,"16l0jzg":`Pattes`,v4q23:`vérifiez le brochage dans sa fiche technique`,gy95h:`Fil de câblage`,"170hkbj":`Fil souple rouge et noir pour les fils des moteurs. Coupez-le à longueur au fur et à mesure.`,"19d4ccc":`Rouge`,ch832v:`la languette la plus proche du centre de la voiture, sur chaque moteur`,bxogn8:`Noir`,"1xdely8":`la languette la plus proche de la roue`,"114bxvb":`Câbles Dupont femelle–femelle`,tq3ghm:`Câbles Dupont avec une fiche à chaque bout qui s’enfoncent sur des broches au pas de 2.54 mm. Les entrées du driver et le capteur prennent un câble entier par broche. Coupé en deux, un câble donne des fils avec une fiche à un seul bout : pour les pièces soudées (la LED, le buzzer) et pour l’alimentation du driver, dont les autres bouts vont sous les vis de la fiche.`,xe6ekx:`Pas`,terfe0:`15 cm (ceux de 20 cm conviennent aussi : ils font de plus grandes boucles)`,q9r4h7:`Utilisés entiers`,"16oowgw":`8 : quatre entrées du driver, quatre broches du capteur`,"1rf1gzr":`7 : quatre entrées du driver, trois broches du capteur`,onu7hf:`Coupés`,"38aacf":`4 : un rouge et un noir coupés en deux pour les fils de la LED et du buzzer, un rouge et un noir coupés à 12.5 cm d’un bout pour l’alimentation du driver`,"3iidc0":`6 : un rouge et un noir coupés en deux pour les fils de la LED et du buzzer, un orange coupé en deux pour la base du transistor, un rouge et un noir coupés à 11 cm d’un bout pour l’alimentation du driver, et le fil Echo du capteur pour son pont diviseur`,"14fe75h":`Câbles Dupont · capteur à ultrasons`,f96u6l:`Quatre câbles depuis le connecteur du capteur, qui est en haut, en arc vers l’arrière jusqu’au shield. N’importe quelle broche V et n’importe quelle broche G conviennent pour VCC et GND : on prend les plus proches, donc les quatre fils partent en éventail côte à côte.`,tuihok:`Quatre fils depuis le connecteur du capteur, qui est en haut, en arc vers l’arrière jusqu’à la carte d’extension. Echo est un signal 5 V, donc il passe par un pont diviseur 1 kΩ / 2 kΩ (soudé dans son câble, sous gaine) avant d’atteindre le GPIO en 3.3 V.`,ftyyiy:`V de D4`,"1xuokt7":`Trig`,o3rtpx:`S de D4`,gi87tw:`Echo`,m5ulv4:`S de D3`,y9urxb:`G de D2`,"1n4125d":`V de GPIO 32 (réglé sur 5 V)`,p5iwlb:`S de GPIO 32`,"1aj3mnm":`1 kΩ → S de GPIO 35 · 2 kΩ de là à son G`,p0bbcd:`G de GPIO 34`,"1kn37ri":`Câbles Dupont · driver des moteurs`,oiporr:`Les quatre entrées du driver. Chaque paire commande un côté de la voiture : IA porte sa vitesse, sur une broche PWM, et IB son sens.`,z48w8g:`Les quatre entrées du driver, chacune sur une broche capable de PWM. Chaque paire commande un côté de la voiture.`,"11ubulz":`A-IA / A-IB (gauche)`,jf4uze:`B-IA / B-IB (droite)`,"15oeqsr":`Câble du servo`,wowqjs:`Le câble trois fils propre au servo. Il descend par la découpe et remonte par la fente voisine, revient le long du plateau à côté du contrôleur jusqu’au connecteur arrière ; le surplus est replié sous le plateau. Sa fiche 3 voies s’enfiche d’un coup sur un connecteur G / V / S : marron sur G.`,v89fad:`Le câble trois fils propre au servo. Il descend par la découpe et remonte par la fente voisine, revient le long du plateau à côté du contrôleur jusqu’au connecteur arrière ; le surplus est replié sous le plateau. Sa fiche 3 voies s’enfiche d’un coup sur un connecteur G / V / S : marron sur G. La rangée V doit être réglée sur 5 V.`,r6nyn:`Marron`,"1u2gqme":`Orange (signal)`,"1qoi1mz":`S de A5`,ovg5ed:`S de GPIO 23`,"1uovlnp":`Fils de la LED`,"1mffxae":`Une moitié de câble rouge et une moitié de noir, soudées à la LED avec une fiche à l’autre bout. L’anode passe par la résistance de 220 Ω vers une broche de signal ; la cathode va à la masse.`,elp8sy:`Anode (via 220 Ω)`,k62hvj:`S de D13`,ilk009:`Cathode`,k48vv7:`G de D13`,tbj8zu:`S de GPIO 13`,imqrdy:`G de GPIO 13`,"1indwkw":`Fils du buzzer`,"1c2cbqo":`Une moitié de câble rouge et une moitié de noir soudées aux broches du buzzer. Mettez le fil + à HIGH pour biper.`,epsmo4:`Le buzzer est placé entre la broche V en 5 V et le transistor. Mettez le GPIO 21 à HIGH et le transistor relie le − du buzzer à la masse, donc il bipe.`,"1rigupw":`S de A0`,"1yvwce0":`G de A0`,"1tndblu":`V de GPIO 21 (5 V)`,i73cl5:`collecteur du transistor`,a4pty4:`Base (via 1 kΩ)`,obgy0f:`S de GPIO 21`,g663eg:`Câblage d’alimentation`,wp3j1m:`Tout se rejoint sur une fiche DC à deux bornes à vis, enfoncée dans la prise DC de l’UNO. Le + de la batterie arrive à sa borne + par l’interrupteur ; le − de la batterie va directement à sa borne −. Un deuxième fil rouge et un deuxième noir sous les deux mêmes vis portent la tension de la batterie jusqu’aux broches VCC et GND du driver. Le driver ne peut pas être alimenté par les broches 5 V du shield : elles viennent du régulateur de l’UNO, qui fournit au plus quelques centaines de mA.`,"1gazt2h":`Tout se rejoint sur une fiche DC à deux bornes à vis, enfoncée dans la prise DC de la carte d’extension. Le + de la batterie arrive à sa borne + par l’interrupteur ; le − de la batterie va directement à sa borne −. Un deuxième fil rouge et un deuxième noir sous les deux mêmes vis portent la tension de la batterie jusqu’aux broches VCC et GND du driver. Le driver ne peut pas être alimenté par les broches 5 V de la carte : elles viennent de son régulateur, qui fournit au plus quelques centaines de mA.`,"1wuyp3l":`+ de la batterie (via l’interrupteur)`,"161fdmk":`− de la batterie = GND`,"6j9255":`Fiche`,"1qkac6a":`jack de 5.5 × 2.1 mm, centre +, avec bornes à vis`,"1s864ea":`Sous chaque vis`,wj14kx:`deux fils : un de la batterie, un vers le driver`,oz5l6a:`Évitement d’obstacles`,zj0mwn:`Mesurer la distance`,"9jogsy":`À chaque tour de loop(), le capteur envoie un ping. Le sketch note aussi quand la mesure a changé de plus de {changeCm} cm pour la dernière fois : une mesure qui ne bouge pas alors que les roues poussent est le signe que la voiture est coincée.`,"1va2b8a":`Voie libre ?`,yssn5p:`La voie est-elle libre ?`,zou1hc:`Libre signifie rien à moins de {stopCm} cm (STOP_CM), et une mesure qui change encore. La voiture avance alors, et redemande {pingMs} ms plus tard.`,"164owbk":`Avancer`,"2guryp":`LED éteinte, les deux côtés en avant à CRUISE, et une attente de {pingMs} ms : le capteur a besoin de ce temps entre deux pings. Puis un nouveau tour.`,l1vybm:`Arrêt
LED allumée · bip`,ywa890:`Arrêt, LED allumée, un bip court`,"17krb65":`Bloquée ou coincée : les moteurs s’arrêtent, la LED s’allume et le buzzer sonne pendant {beepMs} ms.`,"1njcbjw":`Coincée ?`,"6b9vj0":`Coincée sur quelque chose que le faisceau n’a pas vu ?`,"12aymoo":`Le faisceau du capteur ne fait qu’environ 15° de large, donc la voiture peut accrocher un coin qu’elle n’a jamais vu. Si la mesure n’a pas changé de plus de {changeCm} cm pendant {stuckMsS} alors que la voie semblait libre, la voiture est coincée. (Pas d’écho du tout, 400, ne compte jamais : l’espace libre n’est pas « coincé ».)`,"7k6lib":`Reculer`,ooiwv8:`Elle s’écarte de ce qui la retient pendant {backOffMsS}, et seulement ensuite regarde autour.`,"1d4sv1w":`Regarder à droite, puis à gauche`,"18crqcc":`La tête tourne à {lookRight}° (droite) et à {lookLeft}° (gauche). À chaque fois, le servo a {settleMsS} pour y arriver avant que le capteur soit lu ; les deux mesures sont affichées.`,"1r9o4nf":`Y a-t-il la place de tourner ?`,"122yr22":`Si aucun côté n’a {tightCm} cm (TIGHT_CM), il n’y a pas la place de tourner ici.`,"1i7u6tc":`Reculer, regarder à nouveau`,"1ik4v71":`Reculer et regarder à nouveau`,a0a741:`Coincée de tous côtés : elle recule pendant {backMsS} et regarde à nouveau à droite et à gauche depuis là, autant de fois que nécessaire.`,"1yfjvg4":`Vient de tourner ?`,"2jbjim":`Bloquée à nouveau juste après un virage ?`,"3dv25u":`La tête revient au centre. Ensuite : si le dernier virage s’est terminé il y a moins de {againMsS}, la voiture a à peine bougé depuis qu’elle a tourné.`,"1steplx":`Le même sens à nouveau`,kn4k3y:`Tourner à nouveau dans le même sens`,"1k7wpmb":`Revenir en arrière la ramènerait seulement là où elle était : dans un coin elle tournerait à gauche, à droite, à gauche sans fin. Elle continue donc à tourner dans le sens de son dernier virage, quoi que disent les deux mesures.`,"1lf2d81":`Le côté le plus dégagé`,"1u19y2l":`Tourner vers le côté le plus dégagé`,"1n1zre5":`À gauche si la mesure de gauche est au moins aussi grande que celle de droite, sinon à droite.`,"5j8yhm":`Tourner`,"4h9f4g":`Les deux côtés tournent en sens opposé pendant TURN_MS ({turnMs} ms, environ un quart de tour : réglez-le pour votre sol). Puis la voiture s’arrête, retient dans quel sens elle a tourné et quand, et loop() repart du début.`,mz8bk9:`Mode Auto`,rg9t88:`Dix fois par seconde, loop() envoie un ping avec le capteur et garde la mesure dans distance (elle part vers RoboKit en même temps). En mode Auto, autoStep() décide ensuite quoi en faire.`,"15ai7e9":`Bloquée signifie quelque chose à moins de {stopCm} cm (STOP_CM). La mesure peut dater de {sampleMsS} au plus, donc juste après un virage elle attend {freshMs} ms une mesure prise face à la nouvelle direction. Sinon la voiture continue de rouler.`,"1wwbbaz":`Pendant qu’elle roule, dir vaut "forward" : la fin de loop() le transforme en vitesses des deux moteurs, à la vitesse réglée par RoboKit.`,q8ujdx:`Le faisceau du capteur ne fait qu’environ 15° de large, donc la voiture peut accrocher un coin qu’elle n’a jamais vu. Si la mesure n’a pas changé de plus de {changeCm} cm pendant {stuckMsS} pendant qu’elle roulait, la voiture est coincée : elle recule avant de regarder autour. (Pas d’écho du tout, 400, ne compte jamais : l’espace libre n’est pas « coincé ».)`,"1e83w8t":`La tête tourne à {lookRight}° (droite), puis à {lookLeft}° (gauche). Chaque mesure est prise une fois que le servo a eu le temps d’arriver, et la tête revient au centre.`,"1pjappa":`Si le dernier virage s’est terminé il y a moins de {againMsS}, la voiture a à peine bougé depuis qu’elle a tourné. (Activer Auto repart de zéro : turnedAt vaut alors 0.)`,pjp20w:`Revenir en arrière la ramènerait seulement là où elle était : dans un coin elle tournerait à gauche, à droite, à gauche sans fin. goLeft reste donc tel quel, et la voiture tourne dans le sens de son dernier virage, quoi que disent les deux mesures.`,ihilws:`Les deux côtés tournent en sens opposé pendant TURN_MS ({turnMs} ms, environ un quart de tour : réglez-le pour votre sol). Puis la LED s’éteint, l’heure est notée, et la voiture repart.`,"1k1y69x":`4× moteur TT`,"15bpusl":`8× support de moteur`,dgwrs0:`Boulons, écrous et vis M3`,"1mkf3n0":`4× roue, 65 mm`,"19aemsl":`Driver L9110S`,"123jzux":`coussinet de mousse`,a4iz5j:`Carte d’extension ESP32`,"1al7iyf":`support du capteur`,a89ttz:`Servo SG90`,"1alynuo":`palonnier`,"1pbblc6":`Support 2 × 18650`,muur5i:`2× cellule 18650`,"1t10ooq":`interrupteur`,"7h9qib":`buzzer actif`,"1uw5qdo":`fiche DC`,"1l9u4j2":`16× entretoise M3`,hiufn9:`fil de câblage`,"1w4hkux":`20× câbles Dupont (F–F, 15 cm)`,"1onzquf":`plateau inférieur`,"1h4bzq9":`plateau du milieu`,myp2cd:`plateau supérieur`,pu413r:`Les navigateurs bloquent ws:// depuis une page https:// — lancez RoboKit sur votre ordinateur (npm run dev) pour joindre la voiture`,tqkecz:`Cette page est servie en https, donc le navigateur ne la laisse pas ouvrir ws:// vers la voiture. Pour piloter la vraie voiture, lancez RoboKit sur votre ordinateur (npm install, puis npm run dev) et ouvrez http://localhost:5173.`,vqmrol:`Votre ordinateur doit être sur le réseau « RoboKit », et RoboKit doit être ouvert en http://, pas en https:// : les navigateurs bloquent ws:// depuis les pages sécurisées, donc une copie hébergée en ligne ne peut pas joindre la voiture. Lancez-le sur votre ordinateur (npm install tant que vous avez internet, puis npm run dev) et ouvrez http://localhost:5173.`};export{e as default};